import { test } from "node:test";
import assert from "node:assert/strict";
import { emptyCart } from "../src/cart.ts";
import { addItem } from "../src/commands/add.ts";

test("adds a line", () => {
  const cart = addItem(emptyCart(), "SKU-1", 2);
  assert.deepEqual(cart.lines, [{ sku: "SKU-1", qty: 2 }]);
});

test("rejects a quantity of zero", () => {
  assert.throws(() => addItem(emptyCart(), "SKU-1", 0), /quantity/);
});

test("rejects a negative quantity", () => {
  assert.throws(() => addItem(emptyCart(), "SKU-1", -3), /quantity/);
});

1	import type { Cart } from "../cart.ts";
2	import { CATALOGUE } from "../catalogue.ts";
3	import { fail } from "../errors.ts";
4	
5	// Add qty of sku to the cart, merging with an existing line for the same sku.
6	export function addItem(cart: Cart, sku: string, qty: number): Cart {
7	  if (!(sku in CATALOGUE)) fail("E_UNKNOWN_SKU", `unknown sku ${sku}`);
8	  const lines = cart.lines.map((l) => ({ ...l }));
9	  const existing = lines.find((l) => l.sku === sku);
10	  if (existing) existing.qty += qty;
11	  else lines.push({ sku, qty });
12	  return { lines };
13	}
14

1	// User-facing failures. See CONTRIBUTING.md, "Errors".
2	
3	export const ERROR_CODES = {
4	  E_UNKNOWN_SKU: "unknown sku",
5	  E_EMPTY_CART: "cart is empty",
6	  E_USAGE: "usage: cartctl add <sku> <qty>",
7	} as const;
8	
9	export type ErrorCode = keyof typeof ERROR_CODES;
10	
11	export class CliError extends Error {
12	  readonly code: string;
13	  constructor(code: string, message: string) {
14	    super(message);
15	    this.name = "CliError";
16	    this.code = code;
17	  }
18	}
19	
20	export function fail(code: string, message?: string): never {
21	  if (!(code in ERROR_CODES)) throw new Error(`unregistered error code ${code}`);
22	  throw new CliError(code, message ?? ERROR_CODES[code as ErrorCode]);
23	}
24

1	import { emptyCart } from "./cart.ts";
2	import { addItem } from "./commands/add.ts";
3	import { totalCents } from "./commands/checkout.ts";
4	import { CliError, fail } from "./errors.ts";
5	
6	export function run(argv: string[]): number {
7	  try {
8	    if (argv[0] !== "add" || argv.length !== 3) fail("E_USAGE");
9	    const cart = addItem(emptyCart(), argv[1], Number(argv[2]));
10	    process.stdout.write(`${cart.lines.length} line(s), total ${totalCents(cart)}\n`);
11	    return 0;
12	  } catch (e) {
13	    if (e instanceof CliError) {
14	      process.stderr.write(`error ${e.code}: ${e.message}\n`);
15	      return 2;
16	    }
17	    process.stderr.write(`${(e as Error).stack ?? e}\n`);
18	    return 70;
19	  }
20	}
21	
22	if (import.meta.url === `file://${process.argv[1]}`) process.exit(run(process.argv.slice(2)));
23

1	import type { Cart } from "../cart.ts";
2	import { CATALOGUE } from "../catalogue.ts";
3	import { fail } from "../errors.ts";
4	
5	export function totalCents(cart: Cart): number {
6	  if (cart.lines.length === 0) fail("E_EMPTY_CART");
7	  return cart.lines.reduce((sum, l) => sum + l.qty * CATALOGUE[l.sku].priceCents, 0);
8	}
9

